        # The structure is typically: contents[0].sidebarRenderer.contents[0]....
        # Let's try to find the video renderer
        def find_videos(obj, path=""):
            if isinstance(obj, dict):
                if 'videoId' in obj:
                    return obj
                for k, v in obj.items():
                    result = find_videos(v, f"{path}.{k}")
                    if result:
                        return result
            elif isinstance(obj, list):
                for i, item in enumerate(obj):
                    result = find_videos(item, f"{path}[{i}]")
                    if result:
                        return result
            return None

        video = find_videos(data)
        if video:
            print("Video found:")
            print(json.dumps(video, indent=2)[:2000])
        else:
            print("No video renderer found via search")
            # Print top-level keys
            print("Top-level keys:", list(data.keys())[:20])
    except json.JSONDecodeError as e:
        print(f"JSON parse error: {e}")
        # Print first 500 chars
        print(data_str[:500])
else:
